select 'care', 'Nightingale Health Services LLC', 'Nightingale Health Services LLC', 'دبي', 'برشا هايتس', '+971561680391', 'https://www.nightingaledubai.com', null, 'شركة رعاية صحية منزلية في دبي تقدم التمريض ورعاية كبار السن وجليسات الأطفال والمربيات.', 'https://www.nightingaledubai.com/about-us/', 'تذكر الشركة أنها مرخّصة من هيئة الصحة بدبي للرعاية الصحية المنزلية برقم 0001823. تقدم الرعاية السريرية المنزلية ورعاية كبار السن والرعاية التلطيفية، إلى جانب جليسات الأطفال والمربيات بدوام جزئي ورعاية المواليد.', 'https://www.nightingaledubai.com/wp-content/themes/nightingle/assets/images/logo.svg', null, 'العيادة: 1801 برج العامري، برشا هايتس، دبي؛ المكتب الرئيسي: 1006 برج العامري، برشا هايتس، دبي', null, array['رعاية سريرية منزلية', 'رعاية كبار السن', 'جليسات أطفال ومربيات بدوام جزئي', 'رعاية المواليد وممرضات ليلية', 'تدريب إسعافات أولية للأطفال وتدريب المربيات']::text[], 'أسستها الممرضة آنا ميلور المقيمة في دبي منذ 2004، ويضم فريقها أكثر من 300 مهني صحي.', true
