select 'cleaning', 'Just Shine Cleaning Services', 'Just Shine Cleaning Services', 'أبوظبي', 'Al Danah', '+971552232850', 'https://www.justshinecleaningservices.com/', null, 'شركة تنظيف في أبوظبي تقدم التنظيف العميق وخادمات بالساعة وتنظيف الانتقال للشقق والفلل والمكاتب.', 'https://www.justshinecleaningservices.com/', 'جست شاين لخدمات التنظيف ذ.م.م فريق محلي في أبوظبي يقدم تنظيف المنازل والتنظيف العميق وتنظيف الكنب والسجاد وخادمات بالساعة للشقق والفلل والمكاتب. ويذكر الموقع أنه يخدم 63 منطقة سكنية في أبوظبي.', 'https://www.justshinecleaningservices.com/_next/image?url=%2Fimages%2FLogo%2Ffavicon.jpeg&w=96&q=75', null, 'أبراج الجزيرة، الدانة، المنطقة 1، أبوظبي', null, array['تنظيف عميق', 'خادمات بالساعة', 'تنظيف عند الانتقال والخروج', 'تنظيف ما بعد البناء', 'تنظيف المكاتب والمطاعم']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'cleaning' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Just Shine Cleaning Services'));
