select 'cleaning', 'Pro H Clean', 'Pro H Clean', 'أبوظبي', 'Al Danah', '+971528586569', 'https://prohclean.com/', null, 'شركة تنظيف لها مكتب في أبوظبي تقدم خادمات بالساعة والتنظيف العميق وتنظيف الانتقال، وتخدم الشارقة أيضاً.', 'https://prohclean.com/maids-services-sharjah/', 'تقدم برو إتش كلين خادمات ماهرات للمنازل والشقق والفلل والمكاتب بنظام الساعة أو اليوم أو بشكل دوري، إلى جانب التنظيف العميق وتنظيف الانتقال وتنظيف الكنب والسجاد. ولها مكتب في الدانة بأبوظبي وتخدم مناطق في الشارقة.', 'https://prohclean.com/wp-content/uploads/2023/08/PHC.png', 'info@prohclean.com', 'الدانة، المنطقة 1، أبوظبي', 'https://www.google.com/maps/place/Pro+H+Cleaning+Abu+Dhabi/@24.490555,54.3649651,17z/data=!3m1!4b1!4m6!3m5!1s0x3e5e6749848f0485:0xaa885156fdbd5c39!8m2!3d24.4905501!4d54.3675454!16s%2Fg%2F11vf1fy97x', array['خادمات بالساعة', 'تنظيف عميق', 'تنظيف عند الانتقال والخروج', 'تنظيف الكنب والسجاد', 'تنظيف المكاتب']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'cleaning' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Pro H Clean'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'cleaning', 'Well Expert Cleaning', 'Well Expert Cleaning', 'الشارقة', 'Al Majaz 1', '+971521369524', 'https://wellexpertcleaning.com/', 2019, 'شركة تنظيف ووكالة خادمات في الشارقة منذ 2019 تقدم التنظيف العميق وتنظيف الانتقال وخادمات بالساعة.', 'https://wellexpertcleaning.com/maid-service/', 'ويل إكسبرت لخدمات التنظيف ذ.م.م (شخص واحد) تخدم الشارقة منذ 2019، وتوفر خادمات مدربات بعد التحقق من خلفياتهن بنظام الساعة أو الأسبوع أو الشهر أو الدوام الكامل. وتذكر أنها مرخصة من دائرة التنمية الاقتصادية في الشارقة، ولها مكتب رئيسي في مصفح بأبوظبي.', 'https://wellexpertcleaning.com/wp-content/uploads/2024/06/Well-Expert-Cleaning-Logo.png', 'info@wellexpertcleaning.com', 'شارع الجبرتي، المجاز 1، المجاز، الشارقة', null, array['خادمات بالساعة', 'تنظيف عميق', 'تنظيف عند الانتقال والخروج', 'تنظيف المطابخ والحمامات', 'تنظيف تجاري للمكاتب والمدارس']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'cleaning' and emirate = 'الشارقة' and lower(coalesce(name_en, name_ar)) = lower('Well Expert Cleaning'));
