select 'cleaning', 'Simply Maid UAE', 'Simply Maid UAE', 'عجمان', null, '+971555015899', 'https://simplymaiduae.com/', null, 'شركة تنظيف في عجمان تقدم تنظيف الشقق والفلل وتنظيف الانتقال وما بعد التجديد في عجمان والشارقة.', 'https://simplymaiduae.com/', 'سيمبلي ميد شركة مقرها عجمان تقدم خدمات تنظيف سكنية وتجارية في عجمان والشارقة. وتشمل خدماتها تنظيف الشقق والفلل وتنظيف الانتقال وما بعد التجديد وتنظيف السجاد والستائر والكنب.', 'https://simplymaiduae.com/assets/images/simply-logo-3.png', 'info@simplymaiduae.com', null, null, array['تنظيف الشقق والمنازل', 'تنظيف عند الانتقال والخروج', 'تنظيف ما بعد التجديد', 'تنظيف السجاد والستائر', 'تنظيف تجاري']::text[], 'يذكر الموقع من فريقه علي خان مشرف التنظيف الأول، وله خبرة تزيد على 8 سنوات.', true
where not exists (select 1 from public.service_providers where category = 'cleaning' and emirate = 'عجمان' and lower(coalesce(name_en, name_ar)) = lower('Simply Maid UAE'));
