select 'domestic', 'FamilyCare Center for Domestic Workers Services (Tadbeer Family Care)', 'FamilyCare Center for Domestic Workers Services (Tadbeer Family Care)', 'دبي', 'القوز', '+97142977770', 'https://familycaremaids.ae', 1980, 'مركز تدبير في القوز بدبي لتوظيف العاملات المنزليات والمربيات ومعالجة تأشيراتهن.', 'https://familycaremaids.ae/', 'يصف المركز نفسه بأنه مركز تدبير معتمد من وزارة الموارد البشرية والتوطين في دبي منذ 1980. يتولى التوظيف والعقود والفحص الطبي والهوية الإماراتية وإجراءات التأشيرة عبر منظومة تدبير، مع خيار الاستبدال.', 'https://familycaremaids.ae/main-logo.svg', 'info@tadbeerfamilycare.ae', 'معرض 15، بناية الشفار للاستثمار، شارع الشيخ زايد، القوز، دبي', null, array['عاملات بدوام كامل وجزئي ومقيمات', 'توظيف مربيات أطفال', 'معالجة تأشيرات العمالة المنزلية', 'العقود والفحص الطبي والهوية الإماراتية', 'التجديد والإلغاء والاستبدال']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('FamilyCare Center for Domestic Workers Services (Tadbeer Family Care)'));
