select 'domestic', 'TADBEER Domestic Workers (Housekeeping Domestic Workers Services LLC)', 'TADBEER Domestic Workers (Housekeeping Domestic Workers Services LLC)', 'دبي', 'أم الشيف', '+97147060100', 'https://www.tadbeer.me', null, 'مركز خدمات عمالة منزلية في أم الشيف بدبي يوفر عاملات ومربيات وسائقين ومقدمي رعاية.', 'https://www.tadbeer.me/', 'تذكر الشركة أن مراكزها لخدمات العمالة المنزلية مرخّصة من وزارة الموارد البشرية والتوطين. توفر باقات عمالة مقيمة تشمل العاملات والمربيات والسائقين ومقدمي الرعاية، إلى جانب خدمات التأشيرة والتجديد.', null, 'contact@tadbeer.me', 'مركز خدمات العمالة المنزلية، معرض رقم 4، مبنى إنديغو سكاي، شارع الشيخ زايد، أم الشيف، دبي', 'https://www.google.com/maps/place/TADBEER-+Housekeeping+Co./@25.126649,55.206082,12z/data=!4m5!3m4!1s0x0:0xac81b145355097ed!8m2!3d25.1266492!4d55.2060816?hl=en-US', array['تأشيرات العمالة المنزلية للكفلاء المواطنين والمقيمين', 'باقات عمالة مقيمة: عاملات ومربيات وسائقون', 'استقدام مباشر من الفلبين وإثيوبيا وميانمار وكينيا', 'مقدمو رعاية للأمومة والمواليد وكبار السن', 'خدمات تنظيف ورعاية أطفال عند الطلب']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('TADBEER Domestic Workers (Housekeeping Domestic Workers Services LLC)'));
