select 'domestic', 'Tiger Recruitment (Tiger Private)', 'Tiger Recruitment (Tiger Private)', 'دبي', null, '+97145859309', 'https://tiger-recruitment.com/ae/', null, 'شركة توظيف في دبي لتوظيف السائقين الخاصين وطاقم المنازل لدى العائلات.', 'https://tiger-recruitment.com/ae/looking-to-recruit/hire-a-personal-driver/', 'تتخصص الشركة في توظيف السائقين الخاصين وسائقي العائلات في دبي ومنطقة الشرق الأوسط وشمال أفريقيا ودولياً، بتعيينات دائمة ومؤقتة مع فحص المرشحين والتحقق من مراجعهم. كما توظف طاقم المنازل ومهنيي المكاتب العائلية وطواقم اليخوت، ولها مكاتب في لندن ونيويورك وميامي ودبلن وزيورخ.', 'https://tiger-recruitment.com/wp-content/themes/tiger/images/private-logo.png', null, null, null, array['توظيف سائقين خاصين وسائقي عائلات', 'توظيف طاقم المنازل', 'توظيف مهنيي المكاتب العائلية', 'توظيف طواقم اليخوت', 'تعيينات دائمة ومؤقتة']::text[], 'مديرة ورئيسة منطقة الشرق الأوسط وشمال أفريقيا: Zahra Clark، ويضم الفريق مستشارين سابقين في إدارة العقارات وطواقم اليخوت.', true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Tiger Recruitment (Tiger Private)'));
