select 'domestic', 'Tadbeer Aljawdah (Aljawdah Domestic Workers Services)', 'Tadbeer Aljawdah (Aljawdah Domestic Workers Services)', 'أبوظبي', 'شارع المرور', '+97126322222', 'https://tadbeeraljawdah.ae', null, 'مركز خدمات عمالة منزلية في أبوظبي يوفر عاملات من عدة جنسيات بثلاث باقات.', 'https://tadbeeraljawdah.ae/', 'يوفر المركز عاملات منزليات من الفلبين وإندونيسيا وميانمار وإثيوبيا وسريلانكا وكينيا وأوغندا. يقدم ثلاث باقات: الاستقدام على كفالة العميل، أو على كفالة المركز (تأشيرة تدبير)، أو عاملات شهرياً وبدوام جزئي.', 'https://tadbeeraljawdah.ae/wp-content/uploads/2024/09/cropped-Studio-Project-1.png', 'info@tadbeeraljawdah.ae', 'أبوظبي، شارع المرور، مقابل مدينة زايد', 'https://maps.app.goo.gl/t8MCjAAqm4tSzQpo9', array['استقدام عاملة على كفالة العميل بعقد سنتين', 'عاملة على كفالة المركز (تأشيرة تدبير)', 'عاملات شهرياً أو بدوام جزئي']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Tadbeer Aljawdah (Aljawdah Domestic Workers Services)'));
