select 'domestic', 'Al Maha Domestic Workers Supply Services - Sole Proprietorship', 'Al Maha Domestic Workers Supply Services - Sole Proprietorship', 'أبوظبي', 'نادي الوحدة', null, null, null, 'مركز خدمات عمالة مساعدة مدرج في قائمة المراكز المعتمدة لدى وزارة الموارد البشرية والتوطين في أبوظبي.', 'https://mohre.gov.ae/en/services/approved-services-centers-new1/al-maha-domestic-workers-supply-services-sole-proprietorship', 'مركز لتوريد العمالة المساعدة مدرج في قائمة مراكز الخدمة المعتمدة لدى وزارة الموارد البشرية والتوطين برقم منشأة 936369. يقع في مبنى نادي الوحدة الرياضي الثقافي بأبوظبي.', null, null, 'محل E178B، وحدة E178، نادي الوحدة الرياضي الثقافي، بلوك 7، جزيرة أبوظبي شرق 19', null, '{}'::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Al Maha Domestic Workers Supply Services - Sole Proprietorship'));
