select 'domestic', 'Royal Service Domestic Workers Center (Tadbeer Center Sharjah)', 'Royal Service Domestic Workers Center (Tadbeer Center Sharjah)', 'الشارقة', 'المنطقة الصناعية 6', '+97165199999', 'https://tad-beer.ae/en/', null, 'مركز تدبير في الشارقة يوفر عاملات منزليات ومربيات وجليسات أطفال ومقدمات رعاية.', 'https://tad-beer.ae/en/', 'يصف المركز نفسه بأنه مركز تدبير مرخّص من وزارة الموارد البشرية والتوطين في الشارقة. يوفر عاملات منزليات ومربيات وجليسات أطفال ومدبرات منزل ومقدمات رعاية، ويخدم دبي وأبوظبي وبقية الإمارات.', 'https://tad-beer.ae/images/1200x630/16689916/Royalservicelogo-RPgXOUALjbRvFjxPNfK-qA.png', 'tadbeer@tad-beer.ae', 'شارع الشيخ خليفة بن زايد آل نهيان، بالقرب من توجيه، المنطقة الصناعية 6، الشارقة', null, array['عاملات منزليات', 'مربيات وجليسات أطفال', 'مدبرات منزل', 'مقدمات رعاية']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'الشارقة' and lower(coalesce(name_en, name_ar)) = lower('Royal Service Domestic Workers Center (Tadbeer Center Sharjah)'));
