select 'domestic', 'Zaina Domestic Workers Services', 'Zaina Domestic Workers Services', 'الشارقة', 'الشهباء', null, null, null, 'مركز خدمات عمالة مساعدة في الشارقة مدرج في قائمة المراكز المعتمدة لدى وزارة الموارد البشرية والتوطين.', 'https://mohre.gov.ae/en/services/approved-services-centers-new1/zaina-domestic-workers-services', 'مركز لخدمات العمالة المساعدة مدرج في قائمة مراكز الخدمة المعتمدة لدى وزارة الموارد البشرية والتوطين برقم منشأة 999388. يقع في زوايا ووك مول بمنطقة الشهباء في الشارقة.', null, null, 'زوايا ووك مول، الشهباء، الشارقة', null, '{}'::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'الشارقة' and lower(coalesce(name_en, name_ar)) = lower('Zaina Domestic Workers Services'));
