select 'immigration', 'Henley & Partners', 'Henley & Partners', 'دبي', 'أبراج بحيرات جميرا', '+971 4 392 7722', 'https://www.henleyglobal.com', null, 'مكتب دبي لشركة هينلي آند بارتنرز الدولية للاستشارات في الإقامة والجنسية بالاستثمار.', 'https://www.henleyglobal.com/contact/residence-united-arab-emirates', 'شركة استشارية دولية في التخطيط للإقامة والجنسية تصف نفسها بأنها «شركة المواطنين العالميين». تقدم خدمات الإقامة والجنسية والعقارات والتعليم والكونسيرج، إضافة إلى خدمات للحكومات.', 'https://cdn.henleyglobal.com/themes/hgo/assets/dist/svg/logo.svg', null, 'مكتب 1301، برج ريف، أبراج بحيرات جميرا، ص.ب 213757، دبي، الإمارات', null, array['استشارات الإقامة والجنسية', 'خدمات العقارات', 'خدمات التعليم', 'خدمات الكونسيرج', 'خدمات للحكومات']::text[], null, true
