select 'immigration', 'Savory & Partners', 'Savory & Partners', 'دبي', 'برشاء هايتس', '+971 4 430 1717', 'https://www.savoryandpartners.com', 2010, 'شركة استشارات في الجنسية والإقامة بالاستثمار مقرها دبي، تأسست عام 2010.', 'https://www.savoryandpartners.com/about-us', 'تأسست عام 2010 على يد جيريمي وهيلينا سافوري، وتقدم برامج الجنسية والإقامة بالاستثمار في أكثر من 20 دولة. تذكر أنها وكيل معتمد حكومياً لبرامج سانت لوسيا وغرينادا ودومينيكا وأنتيغوا وباربودا وسانت كيتس ونيفيس.', 'https://cdn.sanity.io/images/yigz6hc1/new_production/b47ed85de1e6e776c20df44e7d708a56efbd714f-176x78.svg', 'info@savoryandpartners.com', 'مكتب 31E01، برج آي رايز، برشاء هايتس، ص.ب 336173، دبي، الإمارات', null, array['الجنسية بالاستثمار (سانت كيتس ونيفيس، غرينادا، مالطا...)', 'الإقامة بالاستثمار (اليونان، الإمارات، البرتغال...)', 'هجرة الأعمال (كندا، بريطانيا، الولايات المتحدة)', 'تأشيرات الرحّالة الرقميين', 'استشارات حماية الأصول وتخطيط المستقبل']::text[], 'أسسها جيريمي وهيلينا سافوري، ويضم فريقها 70 خبيراً في 8 مكاتب بثلاث قارات.', true
where not exists (select 1 from public.service_providers where category = 'immigration' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Savory & Partners'));
