select 'immigration', 'Aussizz Group', 'Aussizz Group', 'دبي', 'أبراج بحيرات جميرا', '+971 58 223 4349', 'https://www.aussizzgroup.com/uae/', null, 'مكتب دبي لمجموعة أوسيز لاستشارات الهجرة والدراسة في أستراليا وكندا ودول أخرى.', 'https://www.aussizzgroup.com/uae/services', 'تقدم المجموعة من مكتبها في دبي استشارات الهجرة إلى أستراليا (التأشيرات المهنية والعائلية والطلابية وغيرها) وبرامج كندا مثل Express Entry وبرنامج الترشيح الإقليمي. كما تقدم إرشاد الدراسة في الخارج والتدريب على اختباري IELTS وPTE، وتذكر أن لديها فريقاً من المختصين المسجلين لدى MARA.', 'https://www.aussizzgroup.com/uae/wp-content/themes/aussizzgroup/assets/images/logo.png', 'dubai@aussizzgroup.com', 'مكتب 2904، برج HDS، المجمع F، أبراج بحيرات جميرا، دبي، الإمارات', null, array['الهجرة إلى أستراليا', 'برامج كندا (Express Entry وPNP)', 'الدراسة في أستراليا وكندا ونيوزيلندا وأمريكا وبريطانيا', 'التدريب على IELTS وPTE', 'خدمات الطلاب (التأمين الصحي وفتح الحسابات)']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'immigration' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Aussizz Group'));
