select 'immigration', 'Fragomen', 'Fragomen', 'أبوظبي', 'أبراج الاتحاد', '+971 2 408 3100', 'https://www.fragomen.com', null, 'مكتب أبوظبي لشركة فراغومن الدولية لخدمات الهجرة وتصاريح العمل والإقامة.', 'https://www.fragomen.com/offices/abu-dhabi.html', 'فرع لشركة فراغومن الدولية لخدمات الهجرة، يقدم استراتيجيات تنقّل الموارد البشرية وتصاريح العمل والإقامة وتأشيرات رجال الأعمال. كما يقدم توثيق المستندات والدعم القنصلي ودعم الشركات التي تتوسع في منطقة الشرق الأوسط وشمال أفريقيا.', null, null, 'أبراج الاتحاد، البرج المكتبي 3، الطابق 25، مكتب 25.04، ص.ب 30275، أبوظبي', null, array['تصاريح العمل والإقامة والحصص', 'تأشيرات رجال الأعمال', 'توثيق المستندات وتصديقها', 'الدعم القنصلي', 'أداة تقييم أهلية الإقامة طويلة الأمد في الإمارات']::text[], null, true
