select 'pets', 'Dubai Kennels & Cattery (DKC)', 'Dubai Kennels & Cattery (DKC)', 'دبي', 'Umm Ramool', '+97142114800', 'https://www.dkc.ae/', 1983, 'مركز في دبي لإيواء الحيوانات الأليفة ورعايتها نهارياً ونقلها دولياً، مع عيادة بيطرية تعمل على مدار الساعة.', 'https://www.dkc.ae/pet-movers', 'تقدم DKC خدمات إيواء ورعاية نهارية للكلاب والقطط والطيور وحيوانات أخرى، إضافة إلى تصدير الحيوانات الأليفة واستيرادها وعبورها عبر الإمارات. وتذكر أنها تدير نقل الحيوانات حول العالم منذ عام 1983، وأنها المناول الرسمي الحصري للحيوانات لدى طيران الإمارات ودناتا في مطار دبي الدولي. ولها عيادة بيطرية تعمل 24 ساعة في موتور سيتي.', 'https://d6hd18130ua9m.cloudfront.net/graphics/DKC-logo.svg', 'boardingdaycare@dkc.ae', 'أم رمول، دبي، بين فستيفال سيتي ومطار دبي الدولي', 'https://www.google.com/maps/place/Dubai+Kennels+%26+Cattery+(DKC)/@25.2208425,55.3733993,17z/data=!3m1!4b1!4m6!3m5!1s0x3e5f676248faec4d:0xc034be7b25029231!8m2!3d25.2208425!4d55.3733993!16s%2Fg%2F1tfs99rf', array['إيواء ورعاية نهارية للحيوانات الأليفة', 'نقل الحيوانات الأليفة دولياً (استيراد وتصدير وعبور)', 'عيادة بيطرية 24/7 في موتور سيتي', 'تجميل الحيوانات أثناء الإقامة', 'توصيل واستلام الحيوانات في أنحاء الدولة']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'pets' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Dubai Kennels & Cattery (DKC)'));
