select 'pets', 'Soaptopia Mobile Pet Grooming', 'Soaptopia Mobile Pet Grooming', 'دبي', 'Al Barsha South', '+971509397039', 'https://soaptopia.ae/', 2015, 'خدمة متنقلة لتجميل الكلاب والقطط والحيوانات الأليفة في منازل العملاء بدبي باستخدام منتجات عضوية.', 'https://soaptopia.ae/', 'سوبتوبيا خدمة تجميل متنقلة في دبي تعمل منذ 2015، وتصل إلى منازل العملاء بعربة مكيفة مجهزة. تستخدم شامبو وبلسماً عضويين معتمدين من وزارة الزراعة الأمريكية، ويخصص لكل حيوان مزين واحد.', 'https://soaptopia.ae/wp-content/uploads/2026/06/soaptopia-logo-1-1.png', 'info@soaptopia.ae', 'مكتب M-02، برج لايت التجاري، البرشاء جنوب 3، دبي', 'https://share.google/UBvm24WyBrKnEt0ES', array['تجميل الكلاب', 'تجميل القطط', 'تجميل الببغاوات والأرانب', 'باقات سبا مميزة', 'تقليم الأظافر وتنظيف الأسنان']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'pets' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Soaptopia Mobile Pet Grooming'));
