select 'pets', 'Crazy Pets', 'Crazy Pets', 'أبوظبي', 'Al Khalidiyah', '+971526020732', 'https://crazypets.ae/', null, 'صالون تجميل للحيوانات الأليفة في الخالدية بأبوظبي يقدم أيضاً التجميل المتنقل وتاكسي الحيوانات.', 'https://crazypets.ae/', 'تقدم كريزي بيتس تجميل الكلاب والقطط والأرانب والطيور في أبوظبي، مع خدمة تجميل متنقلة تشمل العين أيضاً. وتوفر كذلك تاكسي للحيوانات الأليفة ومتجراً للمستلزمات.', 'https://crazypets.ae/wp-content/uploads/crazy-logo.webp', 'booking@crazypets.ae', 'شارع عود الحصان، الخالدية، W9، أبوظبي', 'https://maps.app.goo.gl/x9AuB38khADA3nYb7', array['تجميل الكلاب والقطط', 'تجميل الأرانب والطيور', 'تجميل متنقل في أبوظبي والعين', 'تاكسي الحيوانات الأليفة', 'متجر مستلزمات']::text[], 'تتولى سارة المرزوقي منصب كبيرة المزينين والمديرة.', true
where not exists (select 1 from public.service_providers where category = 'pets' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Crazy Pets'));
