select 'pets', 'Pets Oasis', 'Pets Oasis', 'أم القيوين', null, '+97167662397', 'https://petsoasisuae.com/', 2006, 'منتجع للحيوانات الأليفة في أم القيوين يقدم الإيواء والتجميل والنقل وتاكسي الحيوانات وخدمات بيطرية.', 'https://petsoasisuae.com/', 'تأسست بيتس أوايسس عام 2006، وتضم منتجعاً فاخراً لإيواء الكلاب والقطط والحيوانات الغريبة، وخدمات تجميل ونقل للحيوانات الأليفة وتاكسي وعيادات بيطرية ومتجراً. ولها فروع وأرقام في أم القيوين وأبوظبي ورأس الخيمة.', 'https://petsoasisuae.com/wp-content/uploads/2021/08/logo-white.png', 'info@petsoasisuae.com', null, null, array['منتجع فاخر للكلاب', 'منتجع فاخر للقطط', 'نقل الحيوانات الأليفة', 'تاكسي الحيوانات', 'عيادات بيطرية']::text[], 'أسستها وتديرها الطبيبة البيطرية د. إليزابيث توماس، ويضم الفريق أطباء وفنيين بيطريين وموظفي دعم.', true
where not exists (select 1 from public.service_providers where category = 'pets' and emirate = 'أم القيوين' and lower(coalesce(name_en, name_ar)) = lower('Pets Oasis'));
