select 'pools', 'Al Qamar Pools', 'Al Qamar Pools', 'رأس الخيمة', 'النخيل', '+971 52 103 8600', 'https://alqamargroup.com', null, 'شركة في رأس الخيمة لإنشاء المسابح الخرسانية وتجديدها والأعمال الكهروميكانيكية للمسابح.', 'https://alqamargroup.com/', 'تقدم القمر للمسابح إنشاء المسابح الخرسانية وتجديدها وتبليطها بالفسيفساء، والأعمال الكهروميكانيكية وأعمال المضخات والمحركات. كما تقدم أنظمة الترشيح والأتمتة ومحطات التسخين والتبريد وكشف التسربات والعزل.', 'https://alqamargroup.com/img/logo.jpg', 'support@alqamargroup.com', 'النخيل، شارع اتصالات القديم، رأس الخيمة', null, array['إنشاء المسابح الخرسانية', 'التجديد والتبليط بالفسيفساء', 'الترشيح والأتمتة', 'محطات التسخين والتبريد', 'كشف التسربات والعزل']::text[], null, true
