select 'property_mgmt', 'Provident Real Estate (Provident Estate)', 'Provident Real Estate (Provident Estate)', 'دبي', 'الصفوح 2 (دبي للإعلام)', '+971 4 892 5831', 'https://providentestate.com/', 2008, 'وكالة عقارية في دبي تأسست عام 2008 ولها مكتب مخصص لإدارة العقارات في الصفوح.', 'https://providentestate.com/contact/', 'Provident Real Estate وكالة عقارية في دبي تأسست عام 2008 ومسجلة برقم ORN 1933. تقدم إدارة العقارات بمدير حساب مخصص وإدارة المستأجرين وتحصيل الإيجار والإرشاد القانوني والصيانة والفحص الدوري وبوابة إلكترونية للملاك.', 'https://www.providentestate.com/icons/icon-512x512.png', 'info@providentestate.com', 'بزنس سنترال تاورز، الصفوح 2، دبي', 'https://www.google.com/maps/search/?api=1&query=25.1004487,55.1694916', array['مدير حساب مخصص للمالك', 'إدارة المستأجرين وتحصيل الإيجار', 'الصيانة ومعالجة الشكاوى', 'الفحص الدوري للعقار', 'بوابة ذكية لمتابعة الإيجارات والصيانة']::text[], 'يمثل فريقها أكثر من 22 جنسية ويتحدث أكثر من 45 لغة.', true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Provident Real Estate (Provident Estate)'));
