select 'smart_home', 'Ultrasound LLC (Ultrasound Dubai)', 'Ultrasound LLC (Ultrasound Dubai)', 'دبي', null, '+971 50 4734 678', 'https://www.ultrasounddubai.com/', null, 'شركة متخصصة في تكامل أنظمة المنزل الذكي والصوت والصورة في دبي والإمارات.', 'https://www.ultrasounddubai.com/', 'Ultrasound Dubai شركة متخصصة في المنازل الذكية وتكامل الصوت والصورة، تقدم حلولاً تقنية مخصصة في دبي والإمارات. تشمل خدماتها التحكم بالإضاءة وأتمتة المنازل والسينما المنزلية والستائر الآلية والشبكات وأنظمة الأمن للفلل والشقق والمباني التجارية واليخوت.', 'https://static.wixstatic.com/media/57ca34_dba5c0e49927431babf029bd4704fc2b~mv2.png/v1/fill/w_155,h_79,al_c,q_85,usm_0.66_1.00_0.01,enc_avif,quality_auto/logo_edited.png', null, 'صندوق بريد 72950، دبي، الإمارات العربية المتحدة', null, array['التحكم بالإضاءة وأتمتة المنازل', 'السينما المنزلية', 'توزيع الصوت والصورة', 'الستائر الآلية', 'مشاريع اليخوت']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'smart_home' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Ultrasound LLC (Ultrasound Dubai)'));
