select 'smart_home', 'Runn Automation LLC', 'Runn Automation LLC', 'دبي', 'الخليج التجاري', '+971 4 570 2845', 'https://runn.ae/', null, 'شركة في دبي لأنظمة المنازل والمباني الذكية، ومركز معدات وتدريب ودعم فني لشركات التكامل.', 'https://runn.ae/', 'تتخذ Runn Automation من دبي مقراً وتتخصص في أنظمة المنازل الذكية وإدارة المباني، وتتولى مراحل التكامل من التصميم إلى التركيب والدعم. وهي ممثل رسمي لـ Larnitech وتقدم التدريب للمركّبين والمطورين.', 'https://static.tildacdn.net/tild3037-3166-4935-a333-633062613566/Logo_RUNN_Automation.png', 'sales@runn.ae', 'مكتب 3304، برج بريزم، الخليج التجاري، دبي، الإمارات', 'https://maps.app.goo.gl/1gzVdQWavqip4c7W9', array['فلل نخلة جميرا (Frond N)', 'فيلا جزيرة نوراي، أبوظبي', 'مطعم Virgin Izakaya، دبي', 'أتمتة المباني وأنظمة الأمن المتكاملة']::text[], 'يضم فريقها المعلن مديراً عاماً هو نيكولاي روسانوف إلى جانب مسؤولين تجاريين وتقنيين ومهندسي أتمتة.', true
where not exists (select 1 from public.service_providers where category = 'smart_home' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Runn Automation LLC'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'smart_home', 'The Switch Company', 'The Switch Company', 'دبي', 'عود ميثاء', '+971 56 539 9549', 'https://theswitchcompany.ae/', 2012, 'شركة متخصصة في حلول المنازل الذكية بنظام KNX، والمقر الرئيسي في عود ميثاء بدبي.', 'https://theswitchcompany.ae/', 'شركة متخصصة في حلول المنازل الذكية بنظام KNX، تجمع بين منتجات عالية الجودة وأنظمة موثوقة وخبرة هندسية. تقدم التحكم الذكي في الإضاءة والتكييف والستائر والتحكم الصوتي، إضافة إلى الأمن والسينما المنزلية.', 'https://theswitchcompany.ae/wp-content/uploads/2024/11/footerLogo.svg', 'Info@theswitchcompany.ae', 'مكتب M07، مبنى بزنس أتريوم، عود ميثاء، دبي، الإمارات', 'https://maps.app.goo.gl/dsYRHUtVR1xqM51G9', array['التحكم الذكي بنظام KNX (إضاءة، تكييف، ستائر، تحكم صوتي)', 'حلول الإضاءة المعمارية والخارجية والداخلية', 'أنظمة الأمن: كاميرات مراقبة وإنترفون وتحكم بالدخول', 'السينما المنزلية وأنظمة الصوت', 'التحكم الذكي بالإضاءة في برج الابتكار الشمسي لهيئة كهرباء ومياه دبي (DEWA)']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'smart_home' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('The Switch Company'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'smart_home', 'M K I Smart Living Cine Contracting L.L.C (MK Iconic)', 'M K I Smart Living Cine Contracting L.L.C (MK Iconic)', 'دبي', 'هور العنز الشرقية، ديرة', '+971 54 301 4811', 'https://mkiconic.ae/', null, 'شركة تكامل بريطانية لأنظمة المنازل الذكية والسينما المنزلية لها مكتب في ديرة بدبي.', 'https://mkiconic.ae/', 'تصف MK Iconic نفسها بأنها شركة تكامل بريطانية لها مكاتب في المملكة المتحدة ودبي وفلوريدا، وتقدم أتمتة المنازل والمباني التجارية واليخوت في الإمارات. وتعلن أنها موزع Control4 من فئة Diamond وشريك KNX.', 'https://mkiconic.ae/_next/image?url=/images/brand/logo-dubai.webp&w=1080&q=75', 'uaeoffice@mkiconic.solutions', 'مكتب M17-210، رويال هاوس (M 17)، 24 شارع الوهيدة، هور العنز الشرقية، ديرة، دبي، الإمارات', null, array['فيلا Control4 في تلال الغاف', 'إصلاح نظام KNX لفيلا في جميرا', 'أول تركيب RadioRA 3 في دبي (جرين كوميونيتي)', 'التحكم بالإضاءة والسينما المنزلية والتظليل والأمن']::text[], 'أسسها المهندس مجتبى خوخر.', true
where not exists (select 1 from public.service_providers where category = 'smart_home' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('M K I Smart Living Cine Contracting L.L.C (MK Iconic)'));
