select 'smart_home', 'Emirtech Technology', 'Emirtech Technology', 'أبوظبي', 'مصفح الصناعية', '+971 55 651 7843', 'https://emirtech.ae/', 2018, 'شركة أنظمة أمن وتقنية معلومات وأتمتة منازل تخدم أبوظبي والعين منذ 2018.', 'https://emirtech.ae/home-automation-solutions-uae.html', 'تعمل Emirtech Technology في أنظمة الأمن وتقنية المعلومات وتخدم أبوظبي والعين منذ 2018، وتقدم كاميرات المراقبة والتحكم بالدخول والإنذار وأتمتة المنازل بمهندسين داخليين. وتذكر أنها معتمدة من ADMCC لأنظمة الأمن في إمارة أبوظبي وموزع معتمد لـ Control4.', 'https://emirtech.ae/images/emirtech-logo-400.png', 'sales@emirtech.ae', 'M44، منطقة مصفح الصناعية، أبوظبي، الإمارات العربية المتحدة', 'https://maps.app.goo.gl/NS5BX5jirhuk4drf8', array['أتمتة المنازل (Control4 وKNX)', 'كاميرات المراقبة والأمن', 'التحكم بالدخول', 'الشبكات والتمديدات', 'أنظمة الصوت والصورة']::text[], 'ينفذ تركيب أتمتة المنازل مهندسو الشركة الداخليون.', true
where not exists (select 1 from public.service_providers where category = 'smart_home' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Emirtech Technology'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'smart_home', 'Quicknet Computers', 'Quicknet Computers', 'أبوظبي', 'مصفح (الشعبية ME-11)', '+971 2 553 1474', 'https://quicknet.me/', 2012, 'شركة تكامل منازل ذكية معتمدة KNX ومقرها مصفح في أبوظبي، ولها فرع في العين.', 'https://quicknet.me/smart-home-automation-uae', 'Quicknet Computers جزء من مجموعة Quicknet، وهي شركة تكامل مستقلة لأنظمة Akubela ومعتمدة KNX للمنازل الذكية منذ 2012. تعمل في أبوظبي والعين وتنفذ مشاريع دبي وبقية الإمارات حسب المشروع، وتذكر اعتماد ADMCC وشهادات ISO 9001 وISO 27001.', 'https://quicknet.me/images/logo.jpg', 'jenson@quicknet.me', 'الشعبية ME-11، مصفح، أبوظبي، الإمارات', 'https://maps.app.goo.gl/B2zXCH4Et6iGAkTi8', array['الإضاءة الذكية', 'الستائر والتكييف الذكي', 'الإنترفون والأمن', 'السينما المنزلية', 'التحكم الصوتي']::text[], 'لديها مهندسون داخليون مدربون على معيار KNX ويتحدثون العربية والإنجليزية.', true
where not exists (select 1 from public.service_providers where category = 'smart_home' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Quicknet Computers'));
